    name: "Career 5",
    fileName: "BlockCareer5.vue",
    file: '<template>\n  <!-- \n    Minimal career page with search and featured positions\n    Features: Search bar, featured job highlight, clean minimal design\n  -->\n  <Motion\n    initial="initial"\n    while-in-view="animate"\n    :in-view-options="{ once: true }"\n    as-child\n    :variants="{\n      initial: { opacity: 0 },\n      animate: {\n        opacity: 1,\n        transition: {\n          when: \'beforeChildren\',\n          delayChildren: stagger(0.1),\n        },\n      },\n    }"\n  >\n    <UiContainer class="py-16 lg:py-24">\n      <!-- Header with search -->\n      <div class="mx-auto mb-16 max-w-3xl text-center">\n        <Motion as="h1" :variants="childVariant" class="mb-4 text-4xl font-bold lg:text-5xl">\n          Work with us\n        </Motion>\n        <Motion as="p" :variants="childVariant" class="mb-8 text-lg text-muted-foreground">\n          Help us build products that millions of people love to use\n        </Motion>\n\n        <Motion :variants="childVariant">\n          <div class="relative mx-auto max-w-md">\n            <UiVeeInput placeholder="Search positions..." icon="lucide:search" />\n          </div>\n        </Motion>\n      </div>\n\n      <!-- Featured position -->\n      <Motion :variants="childVariant" class="mb-12">\n        <UiCard class="overflow-hidden border-2 border-primary/20 bg-primary/5 py-0">\n          <UiCardContent class="p-0">\n            <div class="grid grid-cols-1 gap-6 md:grid-cols-12">\n              <!-- Image -->\n              <div class="md:col-span-4">\n                <img\n                  src="https://images.unsplash.com/photo-1600880292203-757bb62b4baf?q=80&w=2070&auto=format&fit=crop"\n                  alt="Featured role"\n                  class="h-full w-full object-cover md:min-h-[300px]"\n                />\n              </div>\n\n              <!-- Content -->\n              <div class="p-6 md:col-span-8 md:flex md:flex-col md:justify-center">\n                <UiBadge class="mb-3 w-fit bg-primary text-primary-foreground">Featured</UiBadge>\n                <h3 class="mb-2 text-2xl font-bold lg:text-3xl">Head of Engineering</h3>\n                <p class="mb-4 text-muted-foreground lg:text-lg">\n                  Lead our engineering team and shape the future of our technology stack. We\'re\n                  looking for a visionary leader with deep technical expertise.\n                </p>\n\n                <div class="mb-4 flex flex-wrap gap-4 text-sm">\n                  <span class="flex items-center gap-2">\n                    <Icon name="lucide:map-pin" class="h-4 w-4 text-primary" />\n                    San Francisco, CA / Remote\n                  </span>\n                  <span class="flex items-center gap-2">\n                    <Icon name="lucide:briefcase" class="h-4 w-4 text-primary" />\n                    Full-time\n                  </span>\n                  <span class="flex items-center gap-2">\n                    <Icon name="lucide:dollar-sign" class="h-4 w-4 text-primary" />\n                    $180k - $250k\n                  </span>\n                </div>\n\n                <div class="flex flex-wrap gap-3">\n                  <UiButton>\n                    Apply now\n                    <Icon name="lucide:arrow-right" class="ml-2 h-4 w-4" />\n                  </UiButton>\n                  <UiButton variant="outline">Learn more</UiButton>\n                </div>\n              </div>\n            </div>\n          </UiCardContent>\n        </UiCard>\n      </Motion>\n\n      <!-- All positions list -->\n      <Motion :variants="childVariant" class="mb-8">\n        <h2 class="text-2xl font-semibold">All open positions</h2>\n      </Motion>\n\n      <div class="space-y-4">\n        <Motion\n          v-for="n in 8"\n          :key="n"\n          :variants="childVariant"\n          :transition="{\n            delay: n * 0.05,\n          }"\n        >\n          <UiCard class="group transition-all hover:border-primary/30 hover:shadow-md">\n            <UiCardContent class="p-6">\n              <div class="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">\n                <div class="flex-1">\n                  <div class="mb-2 flex flex-wrap items-center gap-2">\n                    <h3 class="text-lg font-semibold transition-colors group-hover:text-primary">\n                      Software Engineer\n                    </h3>\n                    <UiBadge variant="outline" size="sm">Engineering</UiBadge>\n                  </div>\n                  <div class="flex flex-wrap gap-4 text-sm text-muted-foreground">\n                    <span class="flex items-center gap-1">\n                      <Icon name="lucide:map-pin" class="h-3.5 w-3.5" />\n                      Remote\n                    </span>\n                    <span class="flex items-center gap-1">\n                      <Icon name="lucide:clock" class="h-3.5 w-3.5" />\n                      Full-time\n                    </span>\n                    <span class="flex items-center gap-1">\n                      <Icon name="lucide:dollar-sign" class="h-3.5 w-3.5" />\n                      $100k - $140k\n                    </span>\n                  </div>\n                </div>\n\n                <div class="flex gap-2">\n                  <UiButton variant="outline" size="sm"> View details </UiButton>\n                  <UiButton size="sm">Apply</UiButton>\n                </div>\n              </div>\n            </UiCardContent>\n          </UiCard>\n        </Motion>\n      </div>\n    </UiContainer>\n  </Motion>\n</template>\n\n<script lang="ts" setup>\n  import { stagger } from "motion-v";\n  import type { MotionProps } from "motion-v";\n\n  const childVariant: MotionProps["variants"] = {\n    initial: { opacity: 0, y: 20 },\n    animate: {\n      opacity: 1,\n      y: 0,\n      transition: {\n        type: "spring",\n        stiffness: 200,\n        damping: 20,\n      },\n    },\n  };\n</script>\n',
