    fileName: "BlockError7.vue",
    file: '<template>\n  <!-- \n    Minimal error page with illustration\n    Features: SVG illustration, clean minimal design, subtle animations\n  -->\n  <Motion\n    initial="initial"\n    while-in-view="animate"\n    :in-view-options="{ once: true }"\n    as-child\n    :variants="{\n      initial: { opacity: 0 },\n      animate: {\n        opacity: 1,\n        transition: {\n          when: \'beforeChildren\',\n          delayChildren: stagger(0.12),\n        },\n      },\n    }"\n  >\n    <div class="flex min-h-screen items-center">\n      <div class="container max-w-2xl text-center">\n        <Motion\n          :variants="{\n            initial: { opacity: 0, scale: 0.8 },\n            animate: {\n              opacity: 1,\n              scale: 1,\n              transition: {\n                type: \'spring\',\n                stiffness: 150,\n                damping: 15,\n              },\n            },\n          }"\n          class="mb-8 inline-block"\n        >\n          <svg\n            class="h-48 w-48 text-primary/20"\n            viewBox="0 0 200 200"\n            fill="none"\n            xmlns="http://www.w3.org/2000/svg"\n          >\n            <circle cx="100" cy="100" r="80" stroke="currentColor" stroke-width="2" />\n            <path\n              d="M70 85 Q70 70 85 70 L115 70 Q130 70 130 85 L130 115 Q130 130 115 130 L85 130 Q70 130 70 115 Z"\n              stroke="currentColor"\n              stroke-width="2"\n              fill="none"\n            />\n            <circle cx="85" cy="90" r="5" fill="currentColor" />\n            <circle cx="115" cy="90" r="5" fill="currentColor" />\n            <path\n              d="M85 115 Q100 105 115 115"\n              stroke="currentColor"\n              stroke-width="2"\n              stroke-linecap="round"\n            />\n          </svg>\n        </Motion>\n\n        <Motion as="h1" :variants="childVariant" class="mb-3 text-6xl font-bold text-primary">\n          {{ statusCode }}\n        </Motion>\n        <Motion\n          as="h2"\n          :variants="childVariant"\n          class="mb-4 text-2xl font-semibold tracking-tight lg:text-3xl"\n        >\n          {{ title }}\n        </Motion>\n        <Motion as="p" :variants="childVariant" class="mb-8 text-muted-foreground">\n          Oops! The page you\'re looking for seems to have wandered off. Don\'t worry, it happens to\n          the best of us.\n        </Motion>\n\n        <Motion\n          as="div"\n          :variants="childVariant"\n          class="flex flex-col items-center justify-center gap-3 sm:flex-row"\n        >\n          <UiButton @click="clearError({ redirect: \'#\' })">\n            <Icon name="lucide:home" class="mr-2 h-4 w-4" />\n            Go Home\n          </UiButton>\n          <UiButton variant="outline" @click="clearError({ redirect: \'#\' })">\n            <Icon name="lucide:arrow-left" class="mr-2 h-4 w-4" />\n            Go Back\n          </UiButton>\n        </Motion>\n      </div>\n    </div>\n  </Motion>\n</template>\n\n<script lang="ts" setup>\n  import { stagger } from "motion-v";\n  import type { MotionProps } from "motion-v";\n\n  const childVariant: MotionProps["variants"] = {\n    initial: { opacity: 0, y: 15 },\n    animate: {\n      opacity: 1,\n      y: 0,\n      transition: {\n        type: "spring",\n        stiffness: 200,\n        damping: 20,\n      },\n    },\n  };\n\n  const props = withDefaults(\n    defineProps<{\n      statusCode?: number;\n      fatal?: boolean;\n      unhandled?: boolean;\n      statusMessage?: string;\n      message?: string;\n      data?: unknown;\n      cause?: unknown;\n    }>(),\n    {\n      statusCode: 404,\n      fatal: false,\n      unhandled: false,\n      statusMessage: "",\n      message: "Page Not Found",\n      data: undefined,\n      cause: undefined,\n    }\n  );\n\n  const title = computed(() => {\n    if (!props.message) return "Error";\n    return props.message;\n  });\n\n  useSeoMeta({ title });\n</script>\n',
