    file: '<template>\n  <UiContainer class="px-4 py-5 md:px-6">\n    <div class="flex flex-col gap-5">\n      <div class="flex flex-wrap items-center justify-between gap-4">\n        <slot name="title">\n          <h1 v-if="props.title" class="text-xl font-bold" v-html="props.title" />\n        </slot>\n        <div class="flex flex-wrap items-center gap-2">\n          <slot name="actions">\n            <UiButton variant="ghost" size="sm">\n              <Icon name="lucide:filter" class="size-4" />\n              Filter\n            </UiButton>\n            <UiButton variant="ghost" size="sm">\n              <Icon name="lucide:download" class="size-4" />\n              Export\n            </UiButton>\n            <UiButton size="sm">\n              <Icon name="lucide:plus" class="size-4" />\n              Add item\n            </UiButton>\n          </slot>\n        </div>\n      </div>\n      <div class="flex flex-col gap-5 md:flex-row md:items-center md:justify-between">\n        <slot name="stats">\n          <div class="grid grid-cols-3 place-items-center md:flex md:flex-wrap md:gap-5">\n            <div class="flex flex-col gap-1">\n              <span class="text-xs font-medium text-muted-foreground">Total items</span>\n              <span class="text-2xl font-bold">{{ props.totalItems }}</span>\n            </div>\n            <UiSeparator orientation="vertical" class="hidden h-12 md:block" />\n            <div class="flex flex-col gap-1">\n              <span class="text-xs font-medium text-muted-foreground">Active</span>\n              <span class="text-2xl font-bold text-primary">{{ props.activeItems }}</span>\n            </div>\n            <UiSeparator orientation="vertical" class="hidden h-12 md:block" />\n            <div class="flex flex-col gap-1">\n              <span class="text-xs font-medium text-muted-foreground">Completed</span>\n              <span class="text-2xl font-bold text-muted-foreground">{{\n                props.completedItems\n              }}</span>\n            </div>\n          </div>\n        </slot>\n        <slot name="search">\n          <div class="relative w-full md:w-64">\n            <UiVeeInput icon="lucide:search" :placeholder="props.searchPlaceholder" />\n          </div>\n        </slot>\n      </div>\n      <UiSeparator />\n    </div>\n  </UiContainer>\n</template>\n\n<script lang="ts" setup>\n  const props = withDefaults(\n    defineProps<{\n      title?: string;\n      totalItems?: number;\n      activeItems?: number;\n      completedItems?: number;\n      searchPlaceholder?: string;\n    }>(),\n    {\n      title: "Tasks",\n      totalItems: 156,\n      activeItems: 42,\n      completedItems: 114,\n      searchPlaceholder: "Search tasks...",\n    }\n  );\n</script>\n',
    category: "Header",
