    name: "Contact Header 4",
    fileName: "BlockContactHeader4.vue",
    file: '<template>\n  <!-- \n    Contact information cards with icons\n    Features: Three-column info cards, icon badges, staggered animations\n  -->\n  <Motion\n    initial="initial"\n    while-in-view="animate"\n    :in-view-options="{ once: true }"\n    as-child\n    :variants="{\n      initial: { opacity: 0 },\n      animate: {\n        opacity: 1,\n        transition: {\n          when: \'beforeChildren\',\n          delayChildren: stagger(0.1),\n        },\n      },\n    }"\n  >\n    <UiContainer class="pb-10">\n      <UiContainer class="py-16 text-center">\n        <slot name="headline">\n          <Motion\n            v-if="headline"\n            as="p"\n            :variants="childVariant"\n            class="font-semibold text-primary"\n          >\n            {{ headline }}\n          </Motion>\n        </slot>\n        <slot name="title">\n          <Motion\n            as="h2"\n            :variants="childVariant"\n            class="mt-2 mb-4 text-4xl font-bold lg:mt-3 lg:mb-6 lg:text-5xl"\n          >\n            {{ title }}\n          </Motion>\n        </slot>\n        <slot name="description">\n          <Motion\n            as="p"\n            :variants="childVariant"\n            class="mx-auto max-w-[800px] text-lg text-muted-foreground lg:text-xl"\n          >\n            {{ description }}\n          </Motion>\n        </slot>\n      </UiContainer>\n      <section class="grid grid-cols-1 gap-8 lg:grid-cols-3">\n        <template v-for="c in contactInfo" :key="c.title">\n          <Motion\n            :variants="childVariant"\n            class="group flex flex-col items-center gap-2 rounded-lg border border-border bg-card p-6 transition-shadow hover:shadow-lg"\n          >\n            <div\n              class="flex h-12 w-12 items-center justify-center rounded-full bg-primary/20 transition-colors group-hover:bg-primary/30"\n            >\n              <Icon :name="c.icon" class="h-6 w-6 text-primary" />\n            </div>\n            <h3 class="mt-4 text-lg font-medium lg:text-xl">{{ c.title }}</h3>\n            <p class="text-center text-muted-foreground">\n              {{ c.description }}\n            </p>\n            <a\n              :href="c.link"\n              target="_blank"\n              class="text-center font-medium text-primary hover:underline"\n            >\n              {{ c.value }}\n            </a>\n          </Motion>\n        </template>\n      </section>\n    </UiContainer>\n  </Motion>\n</template>\n\n<script lang="ts" setup>\n  import { stagger } from "motion-v";\n  import type { MotionProps } from "motion-v";\n\n  const childVariant: MotionProps["variants"] = {\n    initial: { opacity: 0, y: 20 },\n    animate: {\n      opacity: 1,\n      y: 0,\n      transition: {\n        type: "spring",\n        stiffness: 200,\n        damping: 20,\n      },\n    },\n  };\n\n  const contactInfo = [\n    {\n      title: "Email",\n      description: "Our friendly team is here to help.",\n      value: "admin@marketplace.com",\n      icon: "heroicons:envelope",\n      link: "mailto:admin@marketplace.com",\n    },\n    {\n      title: "Office",\n      description: "Come say hello at our office HQ.",\n      value: "100 West Road, Cityvale, SomeCountry",\n      icon: "heroicons:map-pin",\n      link: "#",\n    },\n    {\n      title: "Phone",\n      description: "Mon-Fri from 8am to 5pm.",\n      value: "1-800-123-4567",\n      icon: "heroicons:phone",\n      link: "tel:1-800-123-4567",\n    },\n  ];\n\n  const headline = "Contact us";\n  const title = "We\'d love to hear from you";\n  const description = "Our friendly team is always here to chat.";\n</script>\n',
