    name: "Sidebar Controlled",
    fileName: "BlockSidebarControlled.vue",
    file: '<template>\n  <UiSidebarProvider v-model:open="state">\n    <UiSidebar>\n      <UiSidebarContent>\n        <UiSidebarGroup>\n          <UiSidebarGroupContent>\n            <UiSidebarMenu>\n              <template v-for="(item, index) in items" :key="index">\n                <UiSidebarMenuItem>\n                  <UiSidebarMenuButton as-child>\n                    <NuxtLink :href="item.url">\n                      {{ item.title }}\n                    </NuxtLink>\n                  </UiSidebarMenuButton>\n                  <UiSidebarMenuSub>\n                    <template v-for="(child, k) in item.items" :key="`child-${k}`">\n                      <UiSidebarMenuSubItem>\n                        <UiSidebarMenuSubButton as-child>\n                          <NuxtLink :href="child.url">\n                            {{ child.title }}\n                          </NuxtLink>\n                        </UiSidebarMenuSubButton>\n                      </UiSidebarMenuSubItem>\n                    </template>\n                  </UiSidebarMenuSub>\n                </UiSidebarMenuItem>\n              </template>\n            </UiSidebarMenu>\n          </UiSidebarGroupContent>\n        </UiSidebarGroup>\n      </UiSidebarContent>\n    </UiSidebar>\n    <UiSidebarInset>\n      <UiNavbar sticky>\n        <UiContainer class="flex h-12 items-center">\n          <UiButton size="icon-xs" variant="outline" @click="toggleState">\n            <Icon\n              name="lucide:arrow-right-from-line"\n              class="transition"\n              :class="[state && \'rotate-180\']"\n            />\n            <span class="sr-only">{{ state ? "Close Sidebar" : "Open Sidebar" }}</span>\n          </UiButton>\n        </UiContainer>\n      </UiNavbar>\n      <UiContainer class="py-5">\n        <UiPlaceholder class="h-[450px]">\n          <p>\n            The sidebar is currently <strong>{{ state ? "open" : "closed" }}</strong\n            >.\n          </p>\n        </UiPlaceholder>\n      </UiContainer>\n    </UiSidebarInset>\n  </UiSidebarProvider>\n</template>\n\n<script lang="ts" setup>\n  const state = ref(false);\n  const toggleState = () => (state.value = !state.value);\n  const items = [\n    {\n      title: "Getting Started",\n      url: "#",\n      items: [\n        {\n          title: "Installation",\n          url: "#",\n        },\n        {\n          title: "Project Structure",\n          url: "#",\n        },\n      ],\n    },\n    {\n      title: "Building Your Application",\n      url: "#",\n      items: [\n        {\n          title: "Routing",\n          url: "#",\n        },\n        {\n          title: "Data Fetching",\n          url: "#",\n          isActive: true,\n        },\n        {\n          title: "Rendering",\n          url: "#",\n        },\n        {\n          title: "Caching",\n          url: "#",\n        },\n        {\n          title: "Styling",\n          url: "#",\n        },\n        {\n          title: "Optimizing",\n          url: "#",\n        },\n        {\n          title: "Configuring",\n          url: "#",\n        },\n        {\n          title: "Testing",\n          url: "#",\n        },\n        {\n          title: "Authentication",\n          url: "#",\n        },\n        {\n          title: "Deploying",\n          url: "#",\n        },\n        {\n          title: "Upgrading",\n          url: "#",\n        },\n        {\n          title: "Examples",\n          url: "#",\n        },\n      ],\n    },\n    {\n      title: "API Reference",\n      url: "#",\n      items: [\n        {\n          title: "Components",\n          url: "#",\n        },\n        {\n          title: "File Conventions",\n          url: "#",\n        },\n        {\n          title: "Functions",\n          url: "#",\n        },\n        {\n          title: "next.config.js Options",\n          url: "#",\n        },\n        {\n          title: "CLI",\n          url: "#",\n        },\n        {\n          title: "Edge Runtime",\n          url: "#",\n        },\n      ],\n    },\n    {\n      title: "Architecture",\n      url: "#",\n      items: [\n        {\n          title: "Accessibility",\n          url: "#",\n        },\n        {\n          title: "Fast Refresh",\n          url: "#",\n        },\n        {\n          title: "Next.js Compiler",\n          url: "#",\n        },\n        {\n          title: "Supported Browsers",\n          url: "#",\n        },\n        {\n          title: "Turbopack",\n          url: "#",\n        },\n      ],\n    },\n  ];\n</script>\n',
